BEGIN
  -- Use the current admission/claim lock order. The promotion lock also
  -- serializes the existing full-thinking baseline source freeze.
  PERFORM pg_advisory_xact_lock(hashtextextended('lab-arena-claim-control', 0));
  PERFORM 1 FROM public.lab_arena_restart_claim_control WHERE singleton FOR UPDATE;
  PERFORM pg_advisory_xact_lock(hashtextextended('lab_arena.baseline_promotion', 0));
  LOCK TABLE public.lab_arena_rounds IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.lab_arena_submissions, public.lab_arena_runs
    IN SHARE ROW EXCLUSIVE MODE;
  SELECT * INTO STRICT r FROM public.lab_arena_rounds WHERE round_id = rid FOR UPDATE;

  IF expected_before !~ '^[0-9a-f]{64}$' OR expected_after !~ '^[0-9a-f]{64}$'
     OR baseline_url !~ '^https://github[.]com/leadpoet/leadpoet-sales-agent/archive/[0-9a-f]{40}[.]tar[.]gz$'
     OR baseline_hash !~ '^sha256:[0-9a-f]{64}$'
     OR registry -> 'schema_version' IS DISTINCT FROM '1'::JSONB
     OR jsonb_typeof(registry -> 'approved_routes') IS DISTINCT FROM 'array'
     OR jsonb_array_length(registry -> 'approved_routes') = 0
     OR jsonb_typeof(registry -> 'baseline_route') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Oct28 activation evidence is not pinned' USING ERRCODE = '55000';
  END IF;
  SELECT jsonb_agg(jsonb_build_array(t.tgname, t.tgenabled, pg_get_triggerdef(t.oid),
      pg_get_functiondef(t.tgfoid), to_jsonb(p) - 'prosrc') ORDER BY t.tgname)
    INTO original_triggers FROM pg_trigger t JOIN pg_proc p ON p.oid = t.tgfoid
    WHERE t.tgrelid = 'public.lab_arena_rounds'::regclass AND NOT t.tgisinternal;
  IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'public.lab_arena_rounds'::regclass
        AND NOT tgisinternal AND tgenabled <> 'O')
     OR NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'public.lab_arena_rounds'::regclass
        AND tgname = 'lab_arena_rounds_write_once' AND tgtype = 27
        AND tgfoid = 'public.lab_arena_rounds_write_once_v1()'::regprocedure)
     OR (SELECT jsonb_build_array(pg_get_userbyid(p.proowner), p.proacl::TEXT,
        p.prosecdef, p.provolatile, p.proconfig, l.lanname)
        FROM pg_proc p JOIN pg_language l ON l.oid = p.prolang
        WHERE p.oid = 'public.lab_arena_rounds_write_once_v1()'::regprocedure)
        IS DISTINCT FROM '["lab_arena_owner","{lab_arena_owner=X/lab_arena_owner}",false,"v",["search_path=pg_catalog"],"plpgsql"]'::JSONB
     OR encode(extensions.digest(pg_get_functiondef(
        'public.lab_arena_rounds_write_once_v1()'::regprocedure), 'sha256'), 'hex')
        <> '835694d66c3d32fd7c64c130159ec7029364f7b64350dc1fbd9fcf70e322d136' THEN
    RAISE EXCEPTION 'Oct28 activation round guard differs' USING ERRCODE = '55000';
  END IF;
  -- An exact replay is a no-op, even if ordinary work has since progressed.
  IF encode(extensions.digest(r.configuration_doc::TEXT, 'sha256'), 'hex') = expected_after THEN
    RETURN;
  END IF;
  IF encode(extensions.digest(r.configuration_doc::TEXT, 'sha256'), 'hex') <> expected_before
     OR r.status <> 'open' OR NOT r.rewards_enabled OR NOT r.promotion_required
     OR r.status_generation <> 0 OR r.stage_generation <> 0 OR r.cancel_reason IS NOT NULL
     OR r.arena_network_name IS DISTINCT FROM 'finney' OR r.arena_netuid IS DISTINCT FROM 71
     OR r.configuration_doc ->> 'mode' IS DISTINCT FROM 'live'
     OR r.configuration_doc ->> 'sourcing_cost_eligibility_policy'
        IS DISTINCT FROM 'successful_calls_flat_per_icp_v1'
     OR r.configuration_doc ? 'reasoning_capture_policy'
     OR r.configuration_doc ? 'reasoning_route_registry'
     OR r.configuration_doc ? 'reasoning_baseline_source_sha256'
     OR jsonb_typeof(r.configuration_doc #> '{schedule,submission_cutoff}') IS DISTINCT FROM 'string'
     -- Reviews can be queued one hour before submission cutoff. Activate
     -- before that window so no worker can hold an old-policy review input.
     OR (r.configuration_doc #>> '{schedule,submission_cutoff}')::TIMESTAMPTZ
          - INTERVAL '1 hour' <= clock_timestamp()
     OR r.champion_funding_frozen OR r.champion_submission_id IS NOT NULL OR r.champion_hotkey IS NOT NULL
     OR r.participants IS NOT NULL OR r.benchmark_ref IS NOT NULL
     OR r.evaluation_date IS NOT NULL OR r.icp_set_date IS NOT NULL
     OR r.confirmation_bank_ref IS NOT NULL OR r.confirmation_bank_hash IS NOT NULL
     OR r.confirmation_cohort IS NOT NULL OR r.stage3_scoring_plan_doc IS NOT NULL
     OR r.champion_fallback_providers IS DISTINCT FROM ARRAY[]::TEXT[]
     OR r.stage1_scoring_plan_doc IS NOT NULL OR r.stage2_scoring_plan_doc IS NOT NULL
     OR r.finalists IS NOT NULL OR r.publication_doc IS NOT NULL OR r.published_at IS NOT NULL
     OR r.promotion_doc IS NOT NULL OR r.baseline_promoted_at IS NOT NULL
     OR r.reward_basis_doc IS NOT NULL OR r.reward_basis_hash IS NOT NULL
     OR r.reward_activated_at IS NOT NULL OR r.effective_reward_epoch IS NOT NULL
     OR r.signing_key_doc IS NOT NULL OR r.king_start_epoch IS NOT NULL
     OR r.king_outcome IS NOT NULL OR r.king_hotkey IS NOT NULL
     OR r.scoring_generation_floor <> 0
     OR EXISTS (SELECT 1 FROM public.lab_arena_runs WHERE round_id = rid)
     OR EXISTS (SELECT 1 FROM public.lab_arena_submissions WHERE round_id = rid
       AND (status = 'frozen' OR is_king OR code_review_status <> 'pending'
         OR code_review_attempts <> 0 OR code_review_doc IS NOT NULL
         OR code_review_claim IS NOT NULL OR code_review_started_at IS NOT NULL
         OR code_review_expires_at IS NOT NULL)) THEN
    RAISE EXCEPTION 'Oct28 activation exact state or intake window differs' USING ERRCODE = '55000';
  END IF;
  next_configuration := (r.configuration_doc - ARRAY[
      'reasoning_activation_status', 'reasoning_activation_reason']) || jsonb_build_object(
    'reasoning_capture_policy', 'full_generated_thinking_v1',
    'training_minimum_icp_coverage_percent', 80,
    'training_maximum_missing_reasoning_percent', 1,
    'reasoning_route_registry', registry,
    'reasoning_baseline_source_sha256', baseline_hash,
    'baseline_source_url', baseline_url,
    'execution_icp_cap_microusd', 6000000,
    'cost_per_company_microusd', 6000000,
    'execution_cap_microusd', 6000000::BIGINT * (
       (r.configuration_doc ->> 'stage_1_icp_count')::INTEGER +
       (r.configuration_doc ->> 'stage_2_icp_count')::INTEGER));
  IF encode(extensions.digest(next_configuration::TEXT, 'sha256'), 'hex') IS DISTINCT FROM expected_after THEN
    RAISE EXCEPTION 'Oct28 activation target configuration differs' USING ERRCODE = '55000';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_array(x.round_id,
      encode(extensions.digest(to_jsonb(x)::TEXT, 'sha256'), 'hex')) ORDER BY x.round_id), '[]'::JSONB)
    INTO other_rounds FROM public.lab_arena_rounds x WHERE round_id <> rid;
  SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY submission_id), '[]'::JSONB)
    INTO submissions FROM public.lab_arena_submissions x WHERE round_id = rid;
  -- This transaction holds the only configuration exception. The original
  -- write-once function, its ACLs, and all other triggers remain unchanged.
  ALTER TABLE public.lab_arena_rounds DISABLE TRIGGER lab_arena_rounds_write_once;
  UPDATE public.lab_arena_rounds SET configuration_doc = next_configuration,
    updated_at = clock_timestamp() WHERE round_id = rid;
  GET DIAGNOSTICS changed = ROW_COUNT;
  ALTER TABLE public.lab_arena_rounds ENABLE TRIGGER lab_arena_rounds_write_once;
  SELECT * INTO STRICT after_row FROM public.lab_arena_rounds WHERE round_id = rid;
  SELECT jsonb_agg(jsonb_build_array(t.tgname, t.tgenabled, pg_get_triggerdef(t.oid),
      pg_get_functiondef(t.tgfoid), to_jsonb(p) - 'prosrc') ORDER BY t.tgname)
    INTO current_triggers FROM pg_trigger t JOIN pg_proc p ON p.oid = t.tgfoid
    WHERE t.tgrelid = 'public.lab_arena_rounds'::regclass AND NOT t.tgisinternal;
  IF changed <> 1 OR after_row.configuration_doc IS DISTINCT FROM next_configuration
     OR (to_jsonb(after_row) - ARRAY['configuration_doc', 'updated_at'])
        IS DISTINCT FROM (to_jsonb(r) - ARRAY['configuration_doc', 'updated_at'])
     OR current_triggers IS DISTINCT FROM original_triggers
     OR (SELECT coalesce(jsonb_agg(jsonb_build_array(x.round_id,
      encode(extensions.digest(to_jsonb(x)::TEXT, 'sha256'), 'hex')) ORDER BY x.round_id), '[]'::JSONB)
         FROM public.lab_arena_rounds x WHERE round_id <> rid) IS DISTINCT FROM other_rounds
     OR (SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY submission_id), '[]'::JSONB)
         FROM public.lab_arena_submissions x WHERE round_id = rid) IS DISTINCT FROM submissions THEN
    RAISE EXCEPTION 'Oct28 activation changed protected state' USING ERRCODE = '55000';
  END IF;
END;
$activate_oct28_full_thinking580$;
COMMIT;
